CREATE TABLE table1(f1 int, f2 int); CREATE INDEX index1 ON table1(f1); CREATE TABLE table2(f1 int, f2 int); WITH RECURSIVE c(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM c WHERE i<3000) INSERT INTO table1 SELECT i, i*i FROM c; WITH RECURSIVE c(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM c WHERE i<3000) INSERT INTO table2 SELECT i, i*i FROM c;